        rules: [
            { word: "Definition", desc: "Bhvishya ma thavani kriya", gujarati: "કોઈપણ પ્રકારની ક્રિયા ભવિષ્યમાં થવાની છે તે દર્શાવવા માટે આ કાળનો ઉપયોગ થાય છે.", example: "I will go to school. He will eat mango.", exampleGujarati: "હું શાળાએ જઈશ. તે કેરી ખાશે." },
            { word: "Affirmative", desc: "Subject + will/shall + V1", gujarati: "હકાર વાક્યમાં Subject + will/shall + V1 + object + other words વપરાય છે.", example: "M.S. Dhoni will play Cricket. I shall write a letter. We shall go to school tomorrow.", exampleGujarati: "એમ.એસ. ધોની ક્રિકેટ રમશે. હું પત્ર લખીશ. અમે આવતીકાલે શાળાએ જઈશું." },
            { word: "Negative", desc: "Subject + will + not + V1", gujarati: "નકાર વાક્યમાં Subject + will + not + V1 + object + other words વપરાય છે.", example: "They will not come tomorrow. You will not read a book. We shall not play a hockey match tomorrow.", exampleGujarati: "તેઓ આવતીકાલે નહીં આવે. તું પુસ્તક વાંચીશ નહીં. અમે આવતીકાલે હોકી મેચ નહીં રમીશું." },
            { word: "Interrogative", desc: "Will + subject + V1 + object?", gujarati: "પ્રશ્ન વાક્યમાં Will + subject + V1 + object + other words + ? વપરાય છે.", example: "Will you speak in English? Will he give you some pens? Will they eat mangoes?", exampleGujarati: "શું તું અંગ્રેજીમાં બોલીશ? શું તે તને થોડી પેન આપશે? શું તેઓ કેરી ખાશે?" },
            { word: "Wh-family", desc: "Wh + will + subject + V1?", gujarati: "Wh પ્રશ્નોમાં Wh + will + subject + V1 + object + other words + ? વપરાય છે.", example: "What will you speak in English? Which song will Maria sing? How many book will he buy?", exampleGujarati: "તું અંગ્રેજીમાં શું બોલીશ? મારિયા કયું ગીત ગાશે? તે કેટલી પુસ્તક ખરીદશે?" },
            { word: "Shall", desc: "I, We sathe", gujarati: "I અને We સાથે shall નો ઉપયોગ થાય છે (પરંપરાગત).", example: "I shall write a letter. We shall go to school tomorrow.", exampleGujarati: "હું પત્ર લખીશ. અમે આવતીકાલે શાળાએ જઈશું." },
            { word: "Will", desc: "Badha subjects sathe", gujarati: "બધા જ નામ તેમજ સર્વનામ સાથે will નો ઉપયોગ થાય છે. આજના મોર્ડન જમાના પ્રમાણે બધા નામ અને સર્વનામ સાથે will નો જ ઉપયોગ કરવામાં આવે છે.", example: "He will come. She will go. They will play. I will write.", exampleGujarati: "તે આવશે. તેણી જશે. તેઓ રમશે. હું લખીશ." },
            { word: "Time words", desc: "Tomorrow, next week, next year", gujarati: "ભવિષ્ય દર્શાવતા શબ્દો — tomorrow, next week, next month, next year, soon, later વગેરે.", example: "I will go to school tomorrow. We shall play next week.", exampleGujarati: "હું આવતીકાલે શાળાએ જઈશ. અમે આવતા સપ્તાહે રમીશું." }
        ],
