            { q: "She had not _____ the house. (sell)", a: "sold", gujarati: "તેણીએ ઘર વેચ્યું ન હતું." },
            { q: "Who had _____ food before the guests came? (take)", a: "taken", gujarati: "મહેમાનો આવે તે પહેલા કોણે ભોજન લીધું હતું?" },
            { q: "Had he _____ the match? (win)", a: "won", gujarati: "શું તેણે મેચ જીતી હતી?" },
            { q: "Had they _____ food before the guests came? (take)", a: "taken", gujarati: "શું મહેમાનો આવે તે પહેલા તેઓએ ભોજન લીધું હતું?" },
            { q: "Had the boys _____ bath? (take)", a: "taken", gujarati: "શું છોકરાઓએ સ્નાન કર્યું હતું?" },
            { q: "I had _____ a letter to him. (post)", a: "posted", gujarati: "મેં તેને પત્ર પોસ્ટ કર્યો હતો." },
            { q: "They had not _____ their work. (finish)", a: "finished", gujarati: "તેઓએ તેમનું કામ પૂરું કર્યું ન હતું." },
            { q: "The boys had _____ flowers before the gardener came. (pluck)", a: "plucked", gujarati: "માળી આવે તે પહેલા છોકરાઓએ ફૂલ તોડ્યાં હતાં." },
            { q: "Had he _____ the school before the bell rang? (reach)", a: "reached", gujarati: "શું ઘંટ વાગે તે પહેલા તે શાળાએ પહોંચી ગયો હતો?" },
            { q: "We had _____ video games. (play)", a: "played", gujarati: "અમે વિડિયો ગેમ્સ રમી હતી." },
            { q: "He had _____ chess easily. (win)", a: "won", gujarati: "તેણે ચેસ સહેલાઈથી જીતી હતી." }
