        rules: [
            { word: "Definition", desc: "Bhutkaal ma chalu thai gayeli ane chalu chalu puri thayeli kriya", gujarati: "કોઈપણ પ્રકારની ક્રિયા ભૂતકાળમાં ચાલુ થઈ ગઈ હોય અને થોડા સમય ચાલુ રહી હોય અને ભૂતકાળમાં જ પૂરી થઈ ગઈ હોય તેવી ક્રિયા દર્શાવવા આ કાળનો ઉપયોગ થાય છે.", example: "I had been watching T.V. since the morning. Divya had been waiting for the bus since 2 o'clock.", exampleGujarati: "હું સવારથી ટી.વી. જોઈ રહ્યો હતો. દિવ્યા ૨ વાગ્યાથી બસની રાહ જોઈ રહી હતી." },
            { word: "Affirmative", desc: "Subject + had + been + V1 ing + since/for", gujarati: "હકાર વાક્યમાં Subject + had + been + V1 ing + object + since/for + time વપરાય છે. બધા subjects સાથે had been વપરાય છે.", example: "I had been watching T.V. since the morning. He had been reading books since the morning. She had been finding the dress since the morning.", exampleGujarati: "હું સવારથી ટી.વી. જોઈ રહ્યો હતો. તે સવારથી પુસ્તકો વાંચી રહ્યો હતો. તેણી સવારથી ડ્રેસ શોધી રહી હતી." },
            { word: "Negative", desc: "Subject + had + not + been + V1 ing + since/for", gujarati: "નકાર વાક્યમાં had + not + been + V1 ing + since/for વપરાય છે.", example: "I had not been watching T.V. since the morning. She had not been taking exercise for many days. He had not been taking care of her for long time.", exampleGujarati: "હું સવારથી ટી.વી. જોઈ રહ્યો ન હતો. તેણી ઘણા દિવસોથી કસરત કરી રહી ન હતી. તે લાંબા સમયથી તેની સંભાળ લઈ રહ્યો ન હતો." },
            { word: "Interrogative", desc: "Had + subject + been + V1 ing + since/for", gujarati: "પ્રશ્ન વાક્યમાં Had + subject + been + V1 ing + object + since/for + time + ? વપરાય છે.", example: "Had you been watching T.V. since the morning? Had you not been enjoying the concert for three hours? Had he been pleading your case for one year?", exampleGujarati: "શું તું સવારથી ટી.વી. જોઈ રહ્યો હતો? શું તેં ત્રણ કલાકથી કોન્સર્ટનો આનંદ માણ્યો ન હતો? શું તે એક વર્ષથી તારો કેસ લડી રહ્યો હતો?" },
            { word: "Wh-family", desc: "Wh + had + subject + been + V1 ing + since/for", gujarati: "Wh પ્રશ્નોમાં Wh + had + subject + been + V1 ing + object + since/for + time + ? વપરાય છે.", example: "Why had you been watching TV since the morning? How had you been waiting to get on the train?", exampleGujarati: "તું સવારથી ટી.વી. કેમ જોઈ રહ્યો હતો? ટ્રેનમાં ચઢવા માટે તું કેવી રીતે રાહ જોઈ રહ્યો હતો?" },
            { word: "Who", desc: "Who + had + been + V1 ing", gujarati: "Who + had + been + V1 ing + object + since/for + time + ? વપરાય છે.", example: "Who had been watching TV since the morning? Who had been knocking at the door?", exampleGujarati: "કોણ સવારથી ટી.વી. જોઈ રહ્યું હતું? કોણ દરવાજો ખખડાવી રહ્યું હતું?" },
            { word: "had been nu use", desc: "Badha subjects sathe had been", gujarati: "આ કાળમાં બધા subjects (I, We, You, He, She, It, They) સાથે had been વપરાય છે.", example: "I had been going. He had been reading. She had been cooking. They had been playing. We had been walking.", exampleGujarati: "હું જઈ રહ્યો હતો. તે વાંચી રહ્યો હતો. તેણી રાંધી રહી હતી. તેઓ રમી રહ્યા હતા. અમે ચાલી રહ્યા હતા." },
            { word: "since nu use", desc: "Chokkas samay mate since", gujarati: "ચોક્કસ સમય બતાવવા માટે since વપરાય છે. since morning, since 2005, since Monday, since childhood વગેરે.", example: "I had been watching T.V. since the morning. She had been working in this firm since 2005. I had been shopping with my elder brother in the fair since the morning.", exampleGujarati: "હું સવારથી ટી.વી. જોઈ રહ્યો હતો. તેણી ૨૦૦૫થી આ કંપનીમાં કામ કરી રહી હતી. હું સવારથી મેળામાં મારા મોટા ભાઈ સાથે ખરીદી કરી રહ્યો હતો." },
            { word: "for nu use", desc: "Samaygala mate for", gujarati: "સમયગાળો બતાવવા માટે for વપરાય છે. for two hours, for five years, for many days વગેરે.", example: "He had been reading books for two hours. They had been playing hockey on that field for three hours. Sonu had been gossiping for two hours.", exampleGujarati: "તે બે કલાકથી પુસ્તકો વાંચી રહ્યો હતો. તેઓ તે મેદાનમાં ત્રણ કલાકથી હોકી રમી રહ્યા હતા. સોનુ બે કલાકથી વાતો કરી રહી હતી." },
            { word: "V1 ing form", desc: "Main verb ma ing lagay", gujarati: "આ કાળમાં મુખ્ય ક્રિયાપદ (V1) માં ing લગાડવામાં આવે છે. ing ના spelling rules ધ્યાનમાં રાખવા પડે છે.", example: "going, coming, eating, drinking, playing, running, swimming, reading, watching", exampleGujarati: "જતું, આવતું, ખાતું, પીતું, રમતું, દોડતું, તરતું, વાંચતું, જોતું" },
            { word: "Past Perfect sathe farak", desc: "Past Perfect Continuous vs Past Perfect", gujarati: "Past Perfect Continuous — ભૂતકાળમાં ચાલુ થયેલી અને ચાલુ રહેલી ક્રિયા. Past Perfect — ભૂતકાળમાં પૂરી થયેલી ક્રિયા.", example: "I had been reading a book for two hours. (Continuous) | I had read a book. (Perfect)", exampleGujarati: "હું બે કલાકથી પુસ્તક વાંચી રહ્યો હતો. (ચાલુ) | મેં પુસ્તક વાંચ્યું હતું. (પૂર્ણ)" },
            { word: "Do bhutkaal na ek sathe", desc: "Be bhutkaal na ek vakya ma na aave", gujarati: "એક વાક્યમાં બે ભૂતકાળના રૂપો ભેગા ન થાય. Past Perfect Continuous + Simple Past — આ સાચી રચના છે.", example: "I had been helping him to do the task before I started the program. (સાચું)", exampleGujarati: "મેં પ્રોગ્રામ શરૂ કર્યો તે પહેલા હું તેને કાર્ય કરવામાં મદદ કરતો હતો. (સાચું)" }
        ],
