        rules: [
            { word: "Definition", desc: "Bhvishya ma chalu thai gayeli ane chalu chalu puri thashe te kriya", gujarati: "કોઈપણ પ્રકારની ક્રિયા ભવિષ્યમાં ચાલુ થઈ ગઈ હશે અને થોડા સમય ચાલુ રહી હોય અને ભવિષ્યમાં જ પૂરી થઈ જશે તેવી ક્રિયા દર્શાવવા આ કાળનો ઉપયોગ થાય છે.", example: "I will have been watching T.V. since the morning. Divya will have been waiting for the bus since 2 o'clock.", exampleGujarati: "હું સવારથી ટી.વી. જોઈ રહ્યો હોઈશ. દિવ્યા ૨ વાગ્યાથી બસની રાહ જોઈ રહી હશે." },
            { word: "Affirmative", desc: "Subject + will + have + been + V1 ing + since/for", gujarati: "હકાર વાક્યમાં Subject + will + have + been + V1 ing + object + since/for + time વપરાય છે. બધા subjects સાથે will have been વપરાય છે.", example: "I will have been watching T.V. since the morning. He will have been reading the book for two hours. She will have been finding the dress since the morning.", exampleGujarati: "હું સવારથી ટી.વી. જોઈ રહ્યો હોઈશ. તે બે કલાકથી પુસ્તક વાંચી રહ્યો હશે. તેણી સવારથી ડ્રેસ શોધી રહી હશે." },
            { word: "Negative", desc: "Subject + will + not + have + been + V1 ing + since/for", gujarati: "નકાર વાક્યમાં will + not + have + been + V1 ing + since/for વપરાય છે.", example: "I will not have been watching T.V. since the morning. I will not have been watching the cricket match for an hour. She will not have been eating sweets for many years.", exampleGujarati: "હું સવારથી ટી.વી. જોઈ રહ્યો નહીં હોઉં. હું એક કલાકથી ક્રિકેટ મેચ જોઈ રહ્યો નહીં હોઉં. તેણી ઘણા વર્ષોથી મીઠાઈ ખાઈ રહી નહીં હોય." },
            { word: "Interrogative", desc: "Will + subject + have + been + V1 ing + since/for", gujarati: "પ્રશ્ન વાક્યમાં Will + subject + have + been + V1 ing + object + since/for + time + ? વપરાય છે.", example: "Will you have been watching T.V. since the morning? Will you have been listening to realistic songs since the morning?", exampleGujarati: "શું તું સવારથી ટી.વી. જોઈ રહ્યો હોઈશ? શું તું સવારથી વાસ્તવિક ગીતો સાંભળી રહ્યો હોઈશ?" },
            { word: "Wh-family", desc: "Wh + will + subject + have + been + V1 ing + since/for", gujarati: "Wh પ્રશ્નોમાં Wh + will + subject + have + been + V1 ing + object + since/for + time + ? વપરાય છે.", example: "Why will you have been watching TV since the morning? Who will have been watching TV since the morning?", exampleGujarati: "તું સવારથી ટી.વી. કેમ જોઈ રહ્યો હોઈશ? કોણ સવારથી ટી.વી. જોઈ રહ્યું હશે?" },
            { word: "Who", desc: "Who + will + have + been + V1 ing", gujarati: "Who + will + have + been + V1 ing + object + since/for + time + ? વપરાય છે.", example: "Who will have been watching TV since the morning? Who will have been buying shirt?", exampleGujarati: "કોણ સવારથી ટી.વી. જોઈ રહ્યું હશે? કોણ શર્ટ ખરીદી રહ્યું હશે?" },
            { word: "will have been nu use", desc: "Badha subjects sathe will have been", gujarati: "આ કાળમાં બધા subjects (I, We, You, He, She, It, They) સાથે will have been વપરાય છે.", example: "I will have been going. He will have been reading. She will have been cooking. They will have been playing. We will have been walking.", exampleGujarati: "હું જઈ રહ્યો હોઈશ. તે વાંચી રહ્યો હશે. તેણી રાંધી રહી હશે. તેઓ રમી રહ્યા હશે. અમે ચાલી રહ્યા હશું." },
            { word: "since nu use", desc: "Chokkas samay mate since", gujarati: "ચોક્કસ સમય બતાવવા માટે since વપરાય છે. since morning, since 2005, since Monday વગેરે.", example: "I will have been watching T.V. since the morning. She will have been working in this firm since 2005.", exampleGujarati: "હું સવારથી ટી.વી. જોઈ રહ્યો હોઈશ. તેણી ૨૦૦૫થી આ કંપનીમાં કામ કરી રહી હશે." },
            { word: "for nu use", desc: "Samaygala mate for", gujarati: "સમયગાળો બતાવવા માટે for વપરાય છે. for two hours, for five years, for 21 hours વગેરે.", example: "He will have been reading the book for two hours. They will have been playing football for an hour. Ali will have been painting the room for 21 hours.", exampleGujarati: "તે બે કલાકથી પુસ્તક વાંચી રહ્યો હશે. તેઓ એક કલાકથી ફૂટબોલ રમી રહ્યા હશે. અલીએ ૨૧ કલાકથી રૂમ રંગી રહ્યો હશે." },
            { word: "V1 ing form", desc: "Main verb ma ing lagay", gujarati: "આ કાળમાં મુખ્ય ક્રિયાપદ (V1) માં ing લગાડવામાં આવે છે. ing ના spelling rules ધ્યાનમાં રાખવા પડે છે.", example: "going, coming, eating, drinking, playing, running, swimming, reading, watching", exampleGujarati: "જતું, આવતું, ખાતું, પીતું, રમતું, દોડતું, તરતું, વાંચતું, જોતું" },
            { word: "Future Perfect sathe farak", desc: "Future Perfect Continuous vs Future Perfect", gujarati: "Future Perfect Continuous — ભવિષ્યમાં ચાલુ થયેલી અને ચાલુ રહેલી ક્રિયા. Future Perfect — ભવિષ્યમાં પૂરી થયેલી ક્રિયા.", example: "I will have been reading a book for two hours. (Continuous) | I will have read a book. (Perfect)", exampleGujarati: "હું બે કલાકથી પુસ્તક વાંચી રહ્યો હોઈશ. (ચાલુ) | મેં પુસ્તક વાંચી લીધું હશે. (પૂર્ણ)" },
            { word: "Time clause ma present", desc: "Time clause ma present tense", gujarati: "Time clause (when, by the time, before, after) ma હંમેશા present tense વપરાય છે, future tense નહીં.", example: "I will have been teaching at this school since 2015.", exampleGujarati: "હું ૨૦૧૫થી આ શાળામાં ભણાવી રહ્યો હોઈશ." }
        ],
