            "💡 Had to = કરવું પડ્યું હતું",
            "💡 Will have to = કરવું પડશે",
            "💡 He/She/It sathe has to",
            "💡 I/We/You/They sathe have to",
            "💡 Past ma had to",
            "💡 Future ma will have to",
            "💡 Negative ma do/does/did + not + have to",
            "💡 Interrogative ma Do/Does/Did + subject + have to",
