            { english: "He might be preparing for the interview.", gujarati: "તે કદાચ ઈન્ટરવ્યુ માટે તૈયાર કરી રહ્યો હોય." },
            { english: "They might have reached home.", gujarati: "તેઓ કદાચ ઘરે પહોંચી ગયા હોય." },
            { english: "You must be regular.", gujarati: "તારે નિયમિત થવું જ જોઈએ." },
            { english: "She must have a licence.", gujarati: "તેણી પાસે લાયસન્સ હોવું જ જોઈએ." },
            { english: "I must read English.", gujarati: "મારે અંગ્રેજી વાંચવું જ જોઈએ." },
            { english: "You must take good marks.", gujarati: "તારે સારા ગુણ લેવા જ જોઈએ." },
            { english: "I must go to the market.", gujarati: "મારે બજારમાં જવું જ જોઈએ." },
            { english: "You must not use mobile phone in the classroom.", gujarati: "તારે વર્ગખંડમાં મોબાઈલ ફોનનો ઉપયોગ કરવો ન જ જોઈએ." },
            { english: "The passengers must not get down from running bus.", gujarati: "મુસાફરોએ દોડતી બસમાંથી નીચે ઉતરવું ન જોઈએ." },
            { english: "They should not spend too much time on social media.", gujarati: "તેઓએ સોશિયલ મીડિયા પર બહુ સમય પસાર કરવો ન જોઈએ." }
